// App.js
import { BrowserRouter, Routes, Route, Navigate, Outlet } from 'react-router-dom';
import { useContext } from 'react';
import AuthContext from './context/AuthContext';
import Login from './pages/Login';
import Register from './pages/Register';
import QuizList from './pages/QuizList';
import TakeQuiz from './pages/TakeQuiz';
import Leaderboard from './pages/Leaderboard';

// 👇 Import admin pages
import AdminDashboard from './pages/Admin/Dashboard';
import AdminQuizList from './pages/Admin/QuizList';
import CreateQuiz from './pages/Admin/CreateQuiz';
import AddQuestion from './pages/Admin/AddQuestion';

const ProtectedRoute = ({ children, adminOnly = false }) => {
  const { user, loading } = useContext(AuthContext);
  if (loading) return <div>Loading...</div>;
  if (!user) return <Navigate to="/login" />;
  if (adminOnly && user.role !== 'admin') return <Navigate to="/quizzes" />;
  return children;
};

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Register />} />

        {/* User routes */}
        <Route path="/quizzes" element={
          <ProtectedRoute><QuizList /></ProtectedRoute>
        } />
        <Route path="/quiz/:id" element={
          <ProtectedRoute><TakeQuiz /></ProtectedRoute>
        } />
        <Route path="/leaderboard" element={<Leaderboard />} />

        {/* 👇 Admin routes */}
        <Route path="/admin/*" element={
          <ProtectedRoute adminOnly>
            <AdminLayout />
          </ProtectedRoute>
        } />

        <Route path="*" element={<Navigate to="/quizzes" />} />
      </Routes>
    </BrowserRouter>
  );
}

// 👇 Admin layout with sidebar
const AdminLayout = () => (
  <>
    <div className="flex">
      <Sidebar />
      <div className="flex-1 p-6">
        <Routes>
          <Route index element={<AdminDashboard />} />
          <Route path="quizzes" element={<AdminQuizList />} />
          <Route path="quizzes/new" element={<CreateQuiz />} />
          <Route path="quizzes/:quizId/questions/new" element={<AddQuestion />} />
        </Routes>
      </div>
    </div>
  </>
);

// 👇 Sidebar component (inline for simplicity)
const Sidebar = () => (
  <div className="w-64 bg-gray-800 text-white min-h-screen">
    <div className="p-4 text-xl font-bold">Admin Panel</div>
    <nav className="mt-4">
      <a href="/admin" className="block p-3 hover:bg-gray-700">Dashboard</a>
      <a href="/admin/quizzes" className="block p-3 hover:bg-gray-700">Manage Quizzes</a>
      <a href="/admin/quizzes/new" className="block p-3 hover:bg-gray-700">Create Quiz</a>
    </nav>
  </div>
);

export default App;
